// Why identityHashCode alone is unsafe:
int fromHash = System.identityHashCode(from);
int toHash = System.identityHashCode(to);
// If fromHash == toHash, falling back to from->to vs to->from deadlocks!

import java.util.*;
import java.util.concurrent.locks.ReentrantLock;

public class LedgerService {
    public static final class Account {
        private final long id;
        private long balance;
        private final ReentrantLock lock = new ReentrantLock();
        public Account(long id, long balance) { this.id = id; this.balance = balance; }
        public long id() { return id; }
    }

    public void transfer(Account from, Account to, long amount) {
        if (amount <= 0) throw new IllegalArgumentException("Amount must be positive");
        if (from.id() == to.id()) return;

        Account first = from.id() < to.id() ? from : to;
        Account second = from.id() < to.id() ? to : from;

        first.lock.lock();
        try {
            second.lock.lock();
            try {
                if (from.balance < amount) throw new IllegalStateException("Insufficient funds");
                from.balance -= amount;
                to.balance += amount;
            } finally {
                second.lock.unlock();
            }
        } finally {
            first.lock.unlock();
        }
    }

    public void batchTransfer(Map<Account, Long> deltas) {
        List<Account> ordered = deltas.keySet().stream()
                .sorted(Comparator.comparingLong(Account::id))
                .distinct()
                .toList();
        List<Account> acquired = new ArrayList<>(ordered.size());
        try {
            for (Account acc : ordered) {
                acc.lock.lock();
                acquired.add(acc);
            }
            for (var entry : deltas.entrySet()) {
                if (entry.getKey().balance + entry.getValue() < 0) {
                    throw new IllegalStateException("Insufficient funds: " + entry.getKey().id());
                }
            }
            deltas.forEach((acc, delta) -> acc.balance += delta);
        } finally {
            for (int i = acquired.size() - 1; i >= 0; i--) {
                acquired.get(i).lock.unlock();
            }
        }
    }
}

while (true) {
    if (first.lock.tryLock(10, TimeUnit.MILLISECONDS)) {
        try {
            if (second.lock.tryLock(10, TimeUnit.MILLISECONDS)) {
                try { /* transfer */ return; } finally { second.lock.unlock(); }
            }
        } finally { first.lock.unlock(); }
    }
    LockSupport.parkNanos(ThreadLocalRandom.current().nextLong(50_000, 500_000));
}

